package local.pocketchat;
import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;
public class DownloadCenterTestActivity extends DownloadCenterActivity {
  @Override public void onCreate(Bundle b){try{DefaultDownloads.Target target=DefaultDownloads.local(this,"round2-native-download.txt");try(java.io.OutputStream out=target.output()){out.write("native-download-fixture".getBytes(java.nio.charset.StandardCharsets.UTF_8));}target.publish();DownloadLibrary.get(this).add(this,J.obj("id","round2-native-saved","uri",target.uri.toString(),"name",target.name,"mime","text/plain","state","saved","location",target.location));}catch(Exception e){throw new IllegalStateException("Native download fixture failed",e);}super.onCreate(b);new Handler(Looper.getMainLooper()).postDelayed(()->{JSONArray checks=new JSONArray(),rows=DownloadLibrary.get(this).list();checks.put(J.obj("name","Opening native download center does not create chat or network","pass",ChatSession.peek()==null));checks.put(J.obj("name","Saved files remain indexed after process recreation","pass",rows.length()>0&&box.getChildCount()>3));boolean label=false;for(int i=0;i<box.getChildCount();i++)if(box.getChildAt(i) instanceof TextView&&((TextView)box.getChildAt(i)).getText().toString().contains("默认位置"))label=true;checks.put(J.obj("name","Download center shows the default folder","pass",label));checks.put(J.obj("name","Native saved file actions are available","pass",actions!=null));try{boolean readable=false;for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row.optString("id").equals("round2-native-saved"))try(java.io.InputStream in=getContentResolver().openInputStream(android.net.Uri.parse(row.optString("uri")))){readable=J.text(in,1024).equals("native-download-fixture");}}checks.put(J.obj("name","Saved fixture opens through the actual read-only provider","pass",readable));J.write(new File(getFilesDir(),"download-center-results.json"),J.obj("checks",checks).toString(2));}catch(Exception ignored){}},200);}
}
